create or replace function public.compute_lead_score(p_person_id uuid,p_property_id uuid) returns jsonb language plpgsql set search_path=public as $$ declare v_score numeric:=0; reasons jsonb:='[]'::jsonb; verified_count int; begin if p_person_id is null or p_property_id is null then return jsonb_build_object('score',0,'tier','cold','reasons','[]'::jsonb); end if; select count(*) into verified_count from contacts c where c.person_id=p_person_id and c.verified=true; if verified_count>0 then v_score:=v_score+0.20; reasons:=reasons||jsonb_build_array('verified_contact'); end if; if exists(select 1 from property_people pp where pp.person_id=p_person_id and pp.property_id=p_property_id) then v_score:=v_score+0.35; reasons:=reasons||jsonb_build_array('direct_property_relationship'); end if; if exists(select 1 from lead_signals ls where ls.person_id=p_person_id and ls.score>=0.60 and ls.observed_at>=now()-interval '30 days') then v_score:=v_score+0.30; reasons:=reasons||jsonb_build_array('recent_strong_signal'); end if; if lower(coalesce((select pe.city from people pe where pe.id=p_person_id),''))=lower(coalesce((select pr.city from properties pr where pr.id=p_property_id),'')) then v_score:=v_score+0.15; reasons:=reasons||jsonb_build_array('same_city'); end if; v_score:=least(1,v_score); return jsonb_build_object('score',v_score,'tier',case when v_score>=0.80 then 'hot' when v_score>=0.60 then 'warm' when v_score>=0.35 then 'cool' else 'cold' end,'reasons',reasons); end; $$;
create or replace function public.materialize_property_matches(p_property_id uuid) returns integer language plpgsql set search_path=public as $$ declare r record; c jsonb; inserted integer:=0; begin for r in select pr.id from properties pr join properties p on p.id=p_property_id where pr.id<>p_property_id and lower(coalesce(pr.city,''))=lower(coalesce(p.city,'')) loop c:=public.score_property_match(p_property_id,r.id); if (c->>'score')::numeric>=0.70 then insert into entity_matches(left_entity_type,left_entity_id,right_entity_type,right_entity_id,match_type,score,reasons,status) values('property',p_property_id,'property',r.id,'property_resolution',(c->>'score')::numeric,c->'reasons','candidate') on conflict do nothing; inserted:=inserted+1; end if; end loop; return inserted; end; $$;
